/**
 * Markdown, rendered through the vocabulary (`design/components/markdown.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/markdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { mergeProps, type JSX } from 'solid-js'

import { claimSlot, resolveSlot, scope, type Defaults } from '@polymorph/solid'
import styles from '@polymorph/recipes/ai/markdown.module.css'
import MarkdownBody from './MarkdownBody'
import Skeleton from '../structure/Skeleton'
import type { CitationSource } from './SourceList'

export type MarkdownSize = NonNullable<MarkdownProps['size']>

export interface MarkdownProps {
  /**
   * The markdown source received so far.
   */
  children: JSX.Element
  /**
   * The body text step (Text's `sm` or `md`), which does not change the heading scale.
   */
  size?: 'sm' | 'md'
  /**
   * The reply's sources in numbered order, which turn each `[n]` in the prose into a Citation to
   * the nth source (without them, `[n]` stays text).
   */
  sources?: CitationSource[]
  /**
   * Whether more is coming, which renders unfinished constructs as text and shows a caret at the
   * end.
   */
  streaming?: boolean
}

/** Markdown, rendered through the vocabulary. */
export default function Markdown(given: MarkdownProps): JSX.Element {
  const props = mergeProps(
    { streaming: false, size: 'md', sources: (() => [])() } as Defaults<
      MarkdownProps,
      'streaming' | 'size' | 'sources'
    >,
    claimSlot(given),
  )
  return scope(() => {
    const childrenSlot = resolveSlot(() => props.children)
    return (
      <div
        class={styles.root}
        data-size={props.size}
        data-state={props.streaming ? 'streaming' : undefined}
        data-pending={props.streaming && childrenSlot.text().trim() === '' ? '' : undefined}
        aria-busy={props.streaming ? true : undefined}
        data-member="markdown"
      >
        {props.streaming && childrenSlot.text().trim() === '' ? (
          <Skeleton shape="text" textStep={props.size} width={9} />
        ) : (
          <MarkdownBody
            source={childrenSlot.text()}
            size={props.size}
            sources={props.sources}
            streaming={props.streaming}
          />
        )}
      </div>
    )
  })
}
